#!/usr/bin/env bash
# Builds OCCT with Silico's deterministic recipe (ARCHITECTURE.md, Deterministic kernel):
# pinned release, verified checksum, verified patch series, pinned clang, no fused or
# build-time-folded math, the libm shim in place of the platform math library (private
# to each library), and no threading library.
#
# Run through pixi so the pinned toolchain is on PATH:  pixi run occt
# Output: target/occt/install/{include,lib}, plus share/silico/recipe.env, which other
# worker C++ (the cxx bridge, PlaneGCS, OndselSolver) reads to build the same way.
# Skips the build when nothing that affects the result has changed.
set -euo pipefail

root=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
here=$root/third_party/occt
scripts=$here/scripts
out=$root/target/occt
install=$out/install
mkdir -p "$out"

read_key() { sed -n "s/^$1=//p" "$here/VERSION"; }
tag=$(read_key tag)
url=$(read_key url)
sha256=$(read_key sha256)

# The recipe's compiler flags.
#   -ffp-contract=off: no fused multiply-add.
#   -fmath-errno and -fno-builtin-<fn> for every inexact math function in
#     scripts/inexact-math.txt: clang never evaluates them at build time with the build
#     machine's library (fold-canary.sh proves it). Targeted, not a blanket -fno-builtin,
#     so exact builtins like sqrt and memcpy stay inline.
#   -stdlib=libc++: the pinned C++ library.
no_builtins=$(awk '!/^#/ && NF {printf "-fno-builtin-%s -fno-builtin-%sf -fno-builtin-%sl ", $1, $1, $1}' "$scripts/inexact-math.txt")
cflags="-ffp-contract=off -fmath-errno ${no_builtins}-stdlib=libc++"

case "$(uname -s)-$(uname -m)" in
  Darwin-arm64)
    triple=aarch64-apple-darwin
    # Apple's ld: lld 21 can't read the macOS 27 SDK.
    ldflags="-fuse-ld=ld -stdlib=libc++"
    hide_flag() { echo "-Wl,-unexported_symbols_list,$1"; }
    defined_syms() { xcrun nm -gU "$1" | awk '{print $NF}'; }
    toolchain_extra() { xcrun --show-sdk-version; ld -v 2>&1 | head -1; }
    ;;
  Linux-x86_64)
    triple=x86_64-unknown-linux-gnu
    ldflags="-fuse-ld=lld -stdlib=libc++"
    hide_flag() { echo "-Wl,--version-script=$1"; }
    defined_syms() { nm -g --defined-only "$1" | awk '{print $NF}'; }
    toolchain_extra() { ldd --version 2>&1 | head -1; }
    ;;
  *)
    echo "occt: unsupported platform $(uname -s)-$(uname -m)" >&2
    exit 1
    ;;
esac

sha256_of() {
  if command -v sha256sum >/dev/null; then sha256sum "$@"; else shasum -a 256 "$@"; fi
}

# Everything that affects the result. A change to any of it forces a rebuild. The
# toolchain part lists exact package versions, not paths, so it's the same in every
# checkout of the same commit.
stamp=$(
  {
    cat "$here/VERSION" "$here/series" "$0" "$scripts/inexact-math.txt"
    while read -r p; do cat "$here/patches/$p"; done < "$here/series"
    cat "$here/libm-shim/Cargo.toml" "$here/libm-shim/Cargo.lock" "$here/libm-shim/src/lib.rs"
    cat "$root/rust-toolchain.toml"
    rustc -V
    clang++ --version | head -1
    ls "$CONDA_PREFIX/conda-meta" | grep '\.json$'
    toolchain_extra
    echo "$triple $cflags $ldflags"
  } | sha256_of | cut -d' ' -f1
)
# The recipe, for other worker C++ to build the same way (M0.4 onwards). Written from
# current paths on every invocation, so moving the checkout never leaves stale paths.
case "$triple" in
  *-apple-darwin) hide_list=$install/share/silico/shim-symbols.txt ;;
  *) hide_list=$install/share/silico/shim-symbols.map ;;
esac
hide=$(hide_flag "$hide_list")
write_recipe() {
  cat > "$1" <<EOF
# Generated by third_party/occt/build.sh, and present only if its checks last passed.
# Build worker C++ with this compiler and these flags. A shared library links the shim
# object privately (the hide flag); executables link it directly (ARCHITECTURE.md).
SILICO_CXX="$(command -v clang++)"
SILICO_CXXFLAGS="$cflags"
SILICO_LDFLAGS="$ldflags"
SILICO_LIBM_SHIM="$install/lib/silico_libm_shim.o"
SILICO_SHIM_HIDE_FLAG="$hide"
EOF
}

# The checks run on every invocation, even when the build is up to date: they take
# seconds, and a change to a check must apply to the existing build too.
run_checks() {
  # shellcheck disable=SC2086
  bash "$scripts/fold-canary.sh" $cflags
  bash "$scripts/verify-patches.sh" "$out/src"
  bash "$scripts/check-math-imports.sh" "$install/lib"
  # shellcheck disable=SC2046
  bash "$scripts/check-shim-hidden.sh" "$install/lib/silico_libm_shim.o" $(ls "$install"/lib/libTK*.dylib "$install"/lib/libTK*.so 2>/dev/null)
  bash "$scripts/check-exceptions.sh"
}

# recipe.env exists only while the checks pass: remove it, check against a fresh copy,
# and publish that copy only on success. A failed check leaves no recipe to trust.
check_and_publish() {
  local recipe=$install/share/silico/recipe.env
  rm -f "$recipe"
  write_recipe "$recipe.tmp"
  SILICO_RECIPE="$recipe.tmp" run_checks
  mv "$recipe.tmp" "$recipe"
}

if [ -f "$install/.stamp" ] && [ "$(cat "$install/.stamp")" = "$stamp" ]; then
  check_and_publish
  echo "occt: up to date ($tag, $triple)"
  exit 0
fi

# 1. The recipe must stop build-time folding of math with this compiler.
# shellcheck disable=SC2086
bash "$scripts/fold-canary.sh" $cflags

# 2. Fetch and verify the pinned release.
tarball=$out/downloads/OCCT-$tag.tar.gz
mkdir -p "$out/downloads"
if [ ! -f "$tarball" ]; then
  echo "occt: downloading $tag"
  curl -fsSL -o "$tarball.part" "$url"
  mv "$tarball.part" "$tarball"
fi
actual=$(sha256_of "$tarball" | cut -d' ' -f1)
if [ "$actual" != "$sha256" ]; then
  echo "occt: checksum mismatch for $tarball" >&2
  echo "  expected $sha256" >&2
  echo "  actual   $actual" >&2
  exit 1
fi

# 3. Extract a fresh tree, apply the series, and prove every patch landed. patch(1),
# not git apply: inside Silico's repository, git apply skips patches and exits 0.
rm -rf "$out/src"
mkdir -p "$out/src"
tar -xzf "$tarball" -C "$out/src" --strip-components=1
while read -r p; do
  echo "occt: applying $p"
  patch -d "$out/src" -p1 --forward --batch --silent < "$here/patches/$p"
done < "$here/series"
bash "$scripts/verify-patches.sh" "$out/src"

# 4. Build the libm shim as one self-contained object.
rm -rf "$out/shim-target"
CARGO_TARGET_DIR=$out/shim-target cargo rustc --quiet \
  --manifest-path "$here/libm-shim/Cargo.toml" --release --target "$triple" \
  --crate-type staticlib -- --emit=obj
built=("$out/shim-target/$triple/release/deps/"silico_libm_shim-*.o)
if [ ${#built[@]} -ne 1 ] || [ ! -f "${built[0]}" ]; then
  echo "occt: expected exactly one shim object, found: ${built[*]}" >&2
  exit 1
fi
if [ -n "$(nm -u "${built[0]}")" ]; then
  echo "occt: libm shim object has undefined symbols:" >&2
  nm -u "${built[0]}" >&2
  exit 1
fi

# 5. Keep the shim's symbols private to each library, so nothing outside binds to
# them by accident (on Linux, global symbol lookup would otherwise hand them out).
rm -rf "$out/build" "$install"
mkdir -p "$install/lib" "$install/share/silico"
shim=$install/lib/silico_libm_shim.o
cp "${built[0]}" "$shim"
case "$triple" in
  *-apple-darwin) defined_syms "$shim" > "$hide_list" ;;
  *) { echo "{ global: *; local:"; defined_syms "$shim" | sed 's/$/;/'; echo "};"; } > "$hide_list" ;;
esac

# 6. Build OCCT's modeling modules with the recipe. BUILD_RELEASE_DISABLE_EXCEPTIONS=OFF:
# OCCT's Release default (-DNo_Exception) compiles out its input checks, so bad input
# (a zero scale, a zero-length direction) comes back as quiet nonsense instead of a
# Standard_Failure the worker can turn into a structured error.
cmake -S "$out/src" -B "$out/build" -G Ninja \
  -DCMAKE_C_COMPILER=clang -DCMAKE_CXX_COMPILER=clang++ \
  -DCMAKE_BUILD_TYPE=Release \
  -DCMAKE_INSTALL_PREFIX="$install" \
  -DCMAKE_C_FLAGS="$cflags" -DCMAKE_CXX_FLAGS="$cflags" \
  -DCMAKE_SHARED_LINKER_FLAGS="$ldflags $hide" \
  -DCMAKE_CXX_STANDARD_LIBRARIES="$shim" \
  -DBUILD_LIBRARY_TYPE=Shared \
  -DBUILD_RELEASE_DISABLE_EXCEPTIONS=OFF \
  -DBUILD_MODULE_FoundationClasses=ON -DBUILD_MODULE_ModelingData=ON -DBUILD_MODULE_ModelingAlgorithms=ON \
  -DBUILD_MODULE_Visualization=OFF -DBUILD_MODULE_ApplicationFramework=OFF -DBUILD_MODULE_DataExchange=OFF \
  -DBUILD_MODULE_Draw=OFF -DBUILD_MODULE_Deprecated=OFF \
  -DUSE_TBB=OFF -DUSE_FREETYPE=OFF -DUSE_OPENGL=OFF -DUSE_TK=OFF -DUSE_FREEIMAGE=OFF \
  -DUSE_RAPIDJSON=OFF -DUSE_DRACO=OFF -DUSE_VTK=OFF -DUSE_GLES2=OFF \
  > "$out/cmake.log" 2>&1 || { tail -30 "$out/cmake.log" >&2; exit 1; }
cmake --build "$out/build" > "$out/build.log" 2>&1 || { grep -E "error|FAILED" "$out/build.log" | head -30 >&2; exit 1; }
cmake --install "$out/build" > "$out/install.log" 2>&1

# 7. No platform math may remain, the shim must stay private, and OCCT must throw.
check_and_publish
echo "$stamp" > "$install/.stamp"
echo "occt: built $tag for $triple"
